import os
import traceback
import logging
from taf.internal.managedobject import ManagedObject
from taf.internal.rpc.pyro.remote_collector import RemoteFileCollectable
from .util import download_files


class Workspace(ManagedObject, RemoteFileCollectable):
    def __init__(self, base_dir, workspace_name, environment, log_dir_name=None):
        super(Workspace, self).__init__()
        self._base_dir = base_dir
        self._workspace_name = workspace_name
        self._workspace_dir = self._generate_workspace_dir()
        self._environment = environment
        self.add_prerequisite(self._environment)
        log_dir_name = log_dir_name or 'logs/'
        log_dir_name = self._normalize_dir(log_dir_name)
        self._log_dir = self._workspace_dir + log_dir_name

    @property
    def is_accessable(self):
        return self._environment and self._environment.is_connected

    @property
    def log_dir(self):
        return self._log_dir

    @property
    def workspace_dir(self):
        return self._workspace_dir

    def create(self):
        self.delete()
        self._mkdirs(self.log_dir)

    def delete(self):
        self._environment.syscommand.rm("-rf", self._workspace_dir)

    def collect_remote_files(self, remote_dir, target_dir=None):

        try:
            file_names = self._environment.syscommand.list_only_files(remote_dir)
            file_paths = [remote_dir + file_name for file_name in file_names]

            download_files(file_paths,
                           self._environment.connection,
                           target_dir or os.getcwd())
        except Exception as e:
            logging.warning("downloading server files failed cause {}, traceback is {}".
                            format(e, traceback.format_exc()))

    def _generate_workspace_dir(self):

        if not self._base_dir:
            """workspace is created for the safety of the operations"""
            workspace_dir = './{workspace}/'.format(workspace=self._workspace_name)
        else:
            base_dir = self._normalize_dir(self._base_dir)
            workspace_dir = base_dir + '{workspace}/'.format(workspace=self._workspace_name)
        return workspace_dir

    @staticmethod
    def _normalize_dir(dir_path):
        normalized_dir = dir_path.replace('\\', '/')
        if not normalized_dir.endswith('/'):
            normalized_dir = normalized_dir + '/'
        return normalized_dir

    def _mkdirs(self, dir_path):
        normalized_path = self._normalize_dir(dir_path)
        self._environment.syscommand.mkdir("-p", normalized_path)
